sum = 0
for i in range(5):
    if i % 2 == 0:
        continue
    sum += i
print(sum)

for i in range(1, 4):
    for j in range(i):
        print(j, end=' ')
    print()

i = 0
while i < 3:
    print(i)
    i += 1
else:
    print('Done')

n = 3
for i in range(n):
    for j in range(n - i):
        print('*', end='')
    print()

found = False
for i in range(5):
    for j in range(5):
        if i * j > 6:
            found = True
            break
    if found:
        break
print(i, j)
